  //       .includes(post.title.toLowerCase())
  //   )[0];
  // const instagramPost = instaCheck ? instaCheck.node.shortcode : false;
  const instagramPost = false;

  function cooking_time(num) {
    let hours = Math.floor(num / 60);
    let minutes = num % 60;
    if (hours === 0) {
      return `${minutes} minutes`;
    } else if (minutes === 0) {
      if (hours === 1) {
        return `${hours} hour`;
      } else {
        return `${hours} hours`;
      }
    } else {
      if (hours === 1) {
        return `${hours} hour and ${minutes} minutes`;
      } else {
        return `${hours} hours and ${minutes} minutes`;
      }
    }
  }
  function category_list(cat) {
    let str = [];
    for (let i = 0; i < cat.length; i++) {
      if (i === 0) {
        str[i] = `${cat[i]}`;
      } else {
        str[i] = `, ${cat[i]}`;
      }
    }
    return str;
  }

  return (
    <>
      <MetaTags
        description={post.seoDescription}
        type="article"
        title={post.seoTitle}
        url={`post/community/${post.slug.current}`}
        imageSrc={urlFor(post.mainImage).url()}
