              Have you done it?
            </h3>
            <StyledCam />
            <StyledTrend className="flex flex-col justify-around md:pr-10 lg:pr-0">
              <h2 className="lg:hidden text-center font-script">
                Have you done it?
              </h2>
              <h3 className="text-center font-sans uppercase">let us know</h3>
