                            {title}
                          </p>
                        </div>
                      </a>
                    </Link>
                  </li>
                )
            )}
            <Link href="/recipes">
              <a
                href="/recipes"
                className="absolute w-full text-center bottom-0 pb-2 text-base md:text-xl uppercase underline"
              >
                See all
              </a>
            </Link>
          </StyledList>
        </div>
      </article>
    </>
  );
};

const links = `...,
                markDefs[]{
                  ...,
                  _type == "postLink" => {
                    "slug": @.reference->slug,
                    "type": @.reference->_type,
                  }
                }
              `;

const queryPost = groq`*[_type == "recipePost" && slug.current == $slug][0]{
title,
seoTitle,
seoDescription,
slug,
mainImage,
cookingTime,
"name": author->name,
"mealType": mealType[]->title,
"categories": categories[]->title,
shortDescription,
description[]{${links}},
ingredients[]{${links}},
servings,
body[]{${links}},
}`;

const queryRecipes = groq`*[_type == "recipePost" && publishedAt < now() && slug.current != $slug]|order(publishedAt desc){
  title,
  mainImage,
  slug,
  _id,
  "categories": categories[]->title,
  }[0...3]
`;

RecipePost.getInitialProps = async function (context) {
  // const instagram = await fetch(
  //   `https://www.instagram.com/graphql/query/?query_hash=7437567ae0de0773fd96545592359a6b&variables={"id":"34696325585","first":8}`
  // ).then((res) => res.json());
  // It's important to default the slug so that it doesn't return "undefined"
  const { slug = "" } = context.query;
  return {
    post: await client.fetch(queryPost, { slug }),
    recipes: await client.fetch(queryRecipes, { slug }),
    // instagram: instagram,
  };
};

